import { Expression, FeederBuilder, Session, asJava, underlyingSessionTo, wrapFeederBuilder } from "@gatling.io/core";

import { JdbcProtocolBuilder, wrapJdbcProtocolBuilder } from "./protocol";
import { Jdbc, wrapJdbc } from "./request";

export * from "./checks";
export * from "./params";
export * from "./protocol";
export * from "./request";

import {
  JdbcDsl as JvmJdbcDsl,
  JdbcProtocolBuilder$Base as JvmJdbcProtocolBuilderBaseStatic
} from "@gatling.io/jvm-types";

// JdbcDsl.jdbc doesn't get properly generated by java2ts because of conflicts with methods of the same name, but it's
// this very instance
const jvmJdbcProtocolBuilderBase = JvmJdbcProtocolBuilderBaseStatic.INSTANCE;

// internal helper of gatling-jdbc, not part of the generated types
const JvmJdbcDataSources = Java.type<any>("io.gatling.javaapi.jdbc.internal.JdbcDataSources");

export interface JdbcApply {
  /**
   * Bootstrap a JDBC request
   *
   * @param requestName - the name of the request, expressed as a Gatling Expression Language String
   * @returns the next DSL step
   */
  (requestName: string): Jdbc;

  /**
   * Bootstrap a JDBC request
   *
   * @param requestName - the name of the request, expressed as a function
   * @returns the next DSL step
   */
  (requestName: (session: Session) => string): Jdbc;
}

export interface JdbcProtocolBuilderBase {
  /**
   * Open connections to the database with the given JDBC URL. The JDBC driver of the database must
   * be declared in the "gatling.jvmDependencies" section of package.json.
   *
   * @param url - the JDBC URL
   * @returns a new JdbcProtocolBuilder instance
   */
  url(url: string): JdbcProtocolBuilder;

  /**
   * Get connections from a javax.sql.DataSource, configured with driver specific settings. Gatling
   * still pools the connections itself, so pass a plain DataSource, not a pooling one.
   *
   * @param dataSource - the javax.sql.DataSource
   * @returns a new JdbcProtocolBuilder instance
   */
  dataSource(dataSource: unknown): JdbcProtocolBuilder;

  /**
   * Get connections from a javax.sql.DataSource, instantiated from its class name with its public
   * no-arg constructor and configured with its JavaBean setters, like HikariCP's
   * dataSourceClassName and dataSourceProperties. Gatling still pools the connections itself, so
   * pass a plain DataSource class, not a pooling one. The JDBC driver of the database must be
   * declared in the "gatling.jvmDependencies" section of package.json.
   *
   * <p>Each property is set with its setter, for example "databaseName" with setDatabaseName.
   * Values are converted to the type of the setter's parameter: numbers to any numeric type as long
   * as no information is lost, strings to numbers, booleans, chars and enums, arrays element by
   * element, and objects to java.util.Properties.
   *
   * @example
   * ```ts
   * jdbc.dataSource("org.postgresql.ds.PGSimpleDataSource", {
   *   serverNames: ["localhost"],
   *   portNumbers: [5432],
   *   databaseName: "gatling"
   * })
   * ```
   *
   * @param className - the fully qualified name of the javax.sql.DataSource class
   * @param properties - the DataSource properties
   * @returns a new JdbcProtocolBuilder instance
   */
  dataSource(className: string, properties: Record<string, unknown>): JdbcProtocolBuilder;
}

const jdbcApply = (requestName: Expression<string>): Jdbc =>
  wrapJdbc(
    typeof requestName === "function" ? JvmJdbcDsl.jdbc(underlyingSessionTo(requestName)) : JvmJdbcDsl.jdbc(requestName)
  );

const jdbcProtocolBuilderBase: JdbcProtocolBuilderBase = {
  url: (url: string) => wrapJdbcProtocolBuilder(jvmJdbcProtocolBuilderBase.url(url)),
  dataSource: (dataSourceOrClassName: unknown, properties?: Record<string, unknown>) =>
    wrapJdbcProtocolBuilder(
      jvmJdbcProtocolBuilderBase.dataSource(
        typeof dataSourceOrClassName === "string"
          ? JvmJdbcDataSources.create(dataSourceOrClassName, asJava(properties ?? {}))
          : dataSourceOrClassName
      )
    )
};

/**
 * The entrypoint of the JDBC DSL: jdbc.url(...) bootstraps a protocol, jdbc("name") a request
 */
export const jdbc: JdbcApply & JdbcProtocolBuilderBase = Object.assign(jdbcApply, jdbcProtocolBuilderBase);

/**
 * Bootstrap a feeder that loads its records from a database with a SQL query, when the simulation
 * starts. The JDBC driver of the database must be declared in the "gatling.jvmDependencies" section
 * of package.json.
 *
 * @param url - the JDBC URL of the database
 * @param username - the username
 * @param password - the password
 * @param sql - the SQL query
 * @returns a FeederBuilder
 */
export const jdbcFeeder = (url: string, username: string, password: string, sql: string): FeederBuilder<unknown> =>
  wrapFeederBuilder(JvmJdbcDsl.jdbcFeeder(url, username, password, sql));
